const mechanismLabFiles={"tcp_framing.py": "\"\"\"Length-prefixed messages and half-close over an actual loopback TCP connection.\n\nPython 3.9+, standard library. No external endpoint or privileged port.\n\"\"\"\nimport json\nimport queue\nimport socket\nimport struct\nimport threading\n\nLIMIT = 4096\n\n\ndef frame(text):\n    body = text.encode(\"utf-8\")\n    if len(body) > LIMIT:\n        raise ValueError(\"frame_too_large\")\n    return struct.pack(\"!I\", len(body)) + body\n\n\nclass Decoder:\n    def __init__(self):\n        self.buffer = bytearray()\n\n    def feed(self, chunk):\n        self.buffer.extend(chunk)\n        messages = []\n        while len(self.buffer) >= 4:\n            size = struct.unpack(\"!I\", self.buffer[:4])[0]\n            if size > LIMIT:\n                raise ValueError(\"frame_too_large\")\n            if len(self.buffer) < 4 + size:\n                break\n            body = bytes(self.buffer[4:4 + size])\n            del self.buffer[:4 + size]\n            messages.append(body.decode(\"utf-8\"))\n        return messages\n\n    def finish(self):\n        if self.buffer:\n            raise ValueError(\"truncated_frame\")\n\n\ndef parser_probes(wire, expected):\n    # Segmentation is controlled here, independent of the TCP implementation.\n    patterns = [[wire], [wire[i:i + 1] for i in range(len(wire))],\n                [wire[:2], wire[2:7], wire[7:]]]\n    for chunks in patterns:\n        parser, actual = Decoder(), []\n        for chunk in chunks:\n            actual.extend(parser.feed(chunk))\n        parser.finish()\n        assert actual == expected\n    outcomes = {}\n    for name, bad in [(\"oversized\", struct.pack(\"!I\", LIMIT + 1)),\n                      (\"truncated_header\", wire[:2]),\n                      (\"truncated_body\", wire[:-1])]:\n        parser = Decoder()\n        try:\n            parser.feed(bad)\n            parser.finish()\n        except ValueError as error:\n            outcomes[name] = str(error)\n        else:\n            raise AssertionError(\"invalid input was accepted: \" + name)\n    assert outcomes == {\"oversized\": \"frame_too_large\",\n                        \"truncated_header\": \"truncated_frame\",\n                        \"truncated_body\": \"truncated_frame\"}\n    return {\"segmentation_patterns_passed\": len(patterns), **outcomes}\n\n\ndef main():\n    expected = [\"云上训练\", \"恢复完成\"]\n    wire = b\"\".join(frame(text) for text in expected)\n    probes = parser_probes(wire, expected)\n    result = queue.Queue()\n    with socket.socket(socket.AF_INET, socket.SOCK_STREAM) as listener:\n        listener.bind((\"127.0.0.1\", 0))\n        listener.listen(1)\n        listener.settimeout(5)\n\n        def serve():\n            try:\n                with listener.accept()[0] as conn:\n                    conn.settimeout(5)\n                    parser, messages, reads = Decoder(), [], []\n                    while True:\n                        chunk = conn.recv(7)  # A limit, not a message boundary.\n                        if not chunk:\n                            parser.finish()\n                            break\n                        reads.append(len(chunk))\n                        messages.extend(parser.feed(chunk))\n                    assert messages == expected\n                    # The peer closed its sending direction, not its receiving one.\n                    conn.sendall(frame(\"已接收2条\"))\n                    conn.shutdown(socket.SHUT_WR)\n                    result.put({\"messages\": messages, \"recv_chunk_bytes\": reads,\n                                \"server_saw_eof_before_reply\": True})\n            except Exception as error:\n                result.put(error)\n\n        worker = threading.Thread(target=serve, daemon=True)\n        worker.start()\n        with socket.create_connection(listener.getsockname(), timeout=5) as client:\n            for text in expected:\n                client.sendall(frame(text))\n            client.shutdown(socket.SHUT_WR)\n            parser, replies = Decoder(), []\n            while True:\n                chunk = client.recv(7)\n                if not chunk:\n                    parser.finish()\n                    break\n                replies.extend(parser.feed(chunk))\n        worker.join(timeout=5)\n        assert not worker.is_alive(), \"server did not terminate\"\n        server = result.get(timeout=1)\n        if isinstance(server, Exception):\n            raise server\n    assert replies == [\"已接收2条\"]\n    assert sum(server[\"recv_chunk_bytes\"]) == len(wire)\n    assert len(server[\"recv_chunk_bytes\"]) > 2\n    print(json.dumps({\"transport\": \"AF_INET / 127.0.0.1 / TCP\",\n                      \"sendall_calls\": 2, \"wire_bytes\": len(wire),\n                      \"payload_bytes\": [len(x.encode(\"utf-8\")) for x in expected],\n                      \"payload_characters\": [len(x) for x in expected],\n                      \"parser_probes\": probes, \"server\": server,\n                      \"reply_after_half_close\": replies,\n                      \"scope\": \"loopback TCP and parser; no epoll, loss injection or business commit\"},\n                     ensure_ascii=False))\n\n\nif __name__ == \"__main__\":\n    main()\n", "checkpoint_commit.py": "\"\"\"A consistent local checkpoint for scalar SGD with momentum and random inputs.\n\nThis teaching protocol is not torch.distributed.checkpoint or an object store.\n\"\"\"\nimport copy\nimport hashlib\nimport json\nfrom pathlib import Path\nimport random\nimport tempfile\n\nRUN = \"scalar-demo\"\nCONFIG = {\"lr\": 0.05, \"momentum\": 0.9, \"seed\": 17}\nFILES = (\"model.json\", \"optimizer.json\", \"input.json\")\n\n\ndef encoded(value):\n    return json.dumps(value, sort_keys=True, separators=(\",\", \":\")).encode()\n\n\ndef digest(data):\n    return hashlib.sha256(data).hexdigest()\n\n\ndef tuple_tree(value):\n    return tuple(tuple_tree(x) for x in value) if isinstance(value, list) else value\n\n\ndef initial():\n    return {\"step\": 0, \"w\": 0.0, \"velocity\": 0.0, \"cursor\": 0,\n            \"rng\": random.Random(CONFIG[\"seed\"]).getstate()}\n\n\ndef advance(state, count):\n    state = copy.deepcopy(state)\n    rng = random.Random()\n    rng.setstate(tuple_tree(state[\"rng\"]))\n    for _ in range(count):\n        x = (state[\"cursor\"] % 4 + 1) * rng.choice([0.9, 1.1])\n        y = 2 * x\n        gradient = (state[\"w\"] * x - y) * x\n        state[\"velocity\"] = CONFIG[\"momentum\"] * state[\"velocity\"] + gradient\n        state[\"w\"] -= CONFIG[\"lr\"] * state[\"velocity\"]\n        state[\"step\"] += 1\n        state[\"cursor\"] += 1\n    state[\"rng\"] = rng.getstate()\n    return state\n\n\ndef prepare(root, name, state):\n    folder = root / name\n    folder.mkdir()\n    common = {\"run\": RUN, \"step\": state[\"step\"], \"config\": CONFIG}\n    parts = {\"model.json\": {\"w\": state[\"w\"]},\n             \"optimizer.json\": {\"velocity\": state[\"velocity\"]},\n             \"input.json\": {\"cursor\": state[\"cursor\"], \"rng\": state[\"rng\"]}}\n    manifest = {**common, \"files\": {}}\n    for filename, payload in parts.items():\n        data = encoded({**common, **payload})\n        (folder / filename).write_bytes(data)\n        manifest[\"files\"][filename] = {\"bytes\": len(data), \"sha256\": digest(data)}\n    (folder / \"manifest.json\").write_bytes(encoded(manifest))\n    return manifest\n\n\ndef validate(folder):\n    manifest = json.loads((folder / \"manifest.json\").read_text())\n    if set(manifest[\"files\"]) != set(FILES) or manifest[\"config\"] != CONFIG:\n        raise ValueError(\"manifest_contract\")\n    parts = {}\n    for filename in FILES:\n        data = (folder / filename).read_bytes()\n        expected = manifest[\"files\"][filename]\n        if len(data) != expected[\"bytes\"] or digest(data) != expected[\"sha256\"]:\n            raise ValueError(\"file_integrity\")\n        part = json.loads(data)\n        if any(part[k] != manifest[k] for k in (\"run\", \"step\", \"config\")):\n            raise ValueError(\"mixed_generation\")\n        parts[filename] = part\n    if manifest[\"run\"] != RUN or parts[\"input.json\"][\"cursor\"] != manifest[\"step\"]:\n        raise ValueError(\"progress_contract\")\n    return {\"step\": manifest[\"step\"], \"w\": parts[\"model.json\"][\"w\"],\n            \"velocity\": parts[\"optimizer.json\"][\"velocity\"],\n            \"cursor\": parts[\"input.json\"][\"cursor\"],\n            \"rng\": tuple_tree(parts[\"input.json\"][\"rng\"])}\n\n\ndef publish(root, name):\n    validate(root / name)\n    temporary = root / \"CURRENT.tmp\"\n    temporary.write_text(name)\n    temporary.replace(root / \"CURRENT\")  # Same local directory, not a durability proof.\n\n\ndef load(root):\n    return validate(root / (root / \"CURRENT\").read_text())\n\n\ndef main():\n    baseline = advance(initial(), 6)\n    split = advance(initial(), 3)\n    with tempfile.TemporaryDirectory() as directory:\n        root = Path(directory)\n        prepare(root, \"step-0\", initial())\n        publish(root, \"step-0\")\n        # A partially written newer folder is not a committed checkpoint.\n        partial = root / \"partial-3\"\n        partial.mkdir()\n        (partial / \"model.json\").write_bytes(encoded({\"step\": 3, \"w\": split[\"w\"]}))\n        assert load(root)[\"step\"] == 0\n        prepare(root, \"step-3\", split)\n        publish(root, \"step-3\")\n        resumed = advance(load(root), 3)\n        assert resumed == baseline\n        # Keep each file individually valid, but mix step 3 and step 4.\n        prepare(root, \"mixed\", split)\n        fourth = advance(split, 1)\n        mixed_file = root / \"mixed\" / \"optimizer.json\"\n        changed = json.loads(mixed_file.read_text())\n        changed.update(step=4, velocity=fourth[\"velocity\"])\n        data = encoded(changed)\n        mixed_file.write_bytes(data)\n        manifest_path = root / \"mixed\" / \"manifest.json\"\n        manifest = json.loads(manifest_path.read_text())\n        manifest[\"files\"][\"optimizer.json\"] = {\"bytes\": len(data), \"sha256\": digest(data)}\n        manifest_path.write_bytes(encoded(manifest))\n        try:\n            publish(root, \"mixed\")\n        except ValueError as error:\n            mixed_error = str(error)\n        else:\n            raise AssertionError(\"mixed checkpoint accepted\")\n        assert mixed_error == \"mixed_generation\"\n        assert (root / \"CURRENT\").read_text() == \"step-3\"\n        prepare(root, \"corrupt\", split)\n        with (root / \"corrupt\" / \"model.json\").open(\"ab\") as stream:\n            stream.write(b\" \")\n        try:\n            publish(root, \"corrupt\")\n        except ValueError as error:\n            corrupt_error = str(error)\n        else:\n            raise AssertionError(\"corrupted checkpoint accepted\")\n        assert corrupt_error == \"file_integrity\"\n    weights_only = initial()\n    weights_only.update(w=split[\"w\"], step=3, cursor=3)\n    weights_only = advance(weights_only, 3)\n    assert weights_only[\"w\"] != baseline[\"w\"]\n    print(json.dumps({\"continuous_steps\": 6, \"split_steps\": [3, 3],\n                      \"partial_folder_loaded_step\": 0,\n                      \"complete_state_exact_match\": resumed == baseline,\n                      \"final_step\": resumed[\"step\"], \"next_sample_cursor\": resumed[\"cursor\"],\n                      \"weight\": resumed[\"w\"], \"velocity\": resumed[\"velocity\"],\n                      \"weights_only_weight\": weights_only[\"w\"],\n                      \"weights_only_match\": weights_only[\"w\"] == baseline[\"w\"],\n                      \"mixed_generation\": mixed_error, \"corruption\": corrupt_error,\n                      \"pointer_after_failed_publish\": \"step-3\",\n                      \"scope\": \"scalar Python SGD, local files; no PyTorch, ranks, GPU or power-loss test\"}))\n\n\nif __name__ == \"__main__\":\n    main()\n", "approval_receipt.py": "\"\"\"Trusted approval, a signed runner statement, and an actual tool receipt.\n\nFixture-only identities and local HMAC; not OAuth, remote MCP or Kairo.\n\"\"\"\nfrom contextlib import closing\nimport hashlib\nimport hmac\nimport json\nfrom pathlib import Path\nimport sqlite3\nimport subprocess\nimport sys\nimport tempfile\n\nTEST_SIGNING_KEY = b\"public-teaching-fixture-not-a-production-key\"\nINTENT = {\"tool\": \"replace_draft:v1\", \"tenant\": \"A\", \"object\": \"draft\",\n          \"expected_version\": 7, \"amount\": 37}\n\n\ndef canonical(value):\n    return json.dumps(value, sort_keys=True, separators=(\",\", \":\")).encode()\n\n\ndef fingerprint(value):\n    return hashlib.sha256(canonical(value)).hexdigest()\n\n\ndef signed_statement():\n    claim = {\"op\": \"K1\", \"tenant\": \"A\", \"status\": \"success\"}\n    signature = hmac.new(TEST_SIGNING_KEY, canonical(claim), hashlib.sha256).hexdigest()\n    return claim, signature\n\n\ndef check_statement(claim, signature):\n    expected = hmac.new(TEST_SIGNING_KEY, canonical(claim), hashlib.sha256).hexdigest()\n    return hmac.compare_digest(expected, signature)\n\n\ndef connect(path):\n    return closing(sqlite3.connect(path, isolation_level=None))\n\n\ndef initialize(path):\n    with connect(path) as db:\n        db.executescript(\"\"\"\n        CREATE TABLE grants(actor TEXT, tenant TEXT, can_read INT, can_write INT,\n                            PRIMARY KEY(actor, tenant));\n        CREATE TABLE draft(tenant TEXT, object TEXT, version INT, amount INT,\n                           PRIMARY KEY(tenant, object));\n        CREATE TABLE approval(id TEXT PRIMARY KEY, actor TEXT, tenant TEXT,\n                              op TEXT, digest TEXT, expires INT, consumed INT);\n        CREATE TABLE receipt(tenant TEXT, op TEXT, digest TEXT, version INT,\n                             amount INT, PRIMARY KEY(tenant, op));\n        INSERT INTO grants VALUES('user-A','A',1,1),('user-B','B',1,1);\n        INSERT INTO draft VALUES('A','draft',7,0);\n        \"\"\")\n        db.execute(\"INSERT INTO approval VALUES(?,?,?,?,?,?,0)\",\n                   (\"R18\", \"user-A\", \"A\", \"K1\", fingerprint(INTENT), 100))\n\n\ndef authorized(db, actor, tenant, action):\n    row = db.execute(\"SELECT can_read,can_write FROM grants WHERE actor=? AND tenant=?\",\n                     (actor, tenant)).fetchone()\n    return bool(row and row[0 if action == \"read\" else 1])\n\n\ndef apply(path, actor, op, intent, approval_id, now):\n    tenant, value_digest = intent[\"tenant\"], fingerprint(intent)\n    with connect(path) as db:\n        db.execute(\"BEGIN IMMEDIATE\")\n        if not authorized(db, actor, tenant, \"write\"):\n            db.rollback()\n            return \"denied\"\n        existing = db.execute(\"SELECT digest FROM receipt WHERE tenant=? AND op=?\",\n                              (tenant, op)).fetchone()\n        if existing:\n            db.rollback()\n            return \"duplicate\" if existing[0] == value_digest else \"conflict\"\n        approval = db.execute(\"SELECT actor,tenant,op,digest,expires,consumed FROM approval WHERE id=?\",\n                              (approval_id,)).fetchone()\n        if (not approval or approval[:4] != (actor, tenant, op, value_digest)\n                or approval[4] < now or approval[5]):\n            db.rollback()\n            return \"approval_mismatch\"\n        if intent[\"tool\"] != \"replace_draft:v1\":\n            db.rollback()\n            return \"unsupported_tool\"\n        updated = db.execute(\"UPDATE draft SET version=version+1,amount=? \"\n                             \"WHERE tenant=? AND object=? AND version=?\",\n                             (intent[\"amount\"], tenant, intent[\"object\"], intent[\"expected_version\"]))\n        if updated.rowcount != 1:\n            db.rollback()\n            return \"version_conflict\"\n        db.execute(\"UPDATE approval SET consumed=1 WHERE id=?\", (approval_id,))\n        db.execute(\"INSERT INTO receipt VALUES(?,?,?,?,?)\",\n                   (tenant, op, value_digest, intent[\"expected_version\"] + 1, intent[\"amount\"]))\n        db.commit()  # Effect, receipt and approval consumption share this local transaction.\n        return \"committed\"\n\n\ndef lookup(path, actor, tenant, op, injected_timeout=False):\n    with connect(path) as db:\n        if not authorized(db, actor, tenant, \"read\"):\n            return {\"status\": \"denied\"}\n        if injected_timeout:\n            return {\"status\": \"unknown\"}  # Injected adapter failure, not a real network.\n        row = db.execute(\"SELECT digest,version,amount FROM receipt WHERE tenant=? AND op=?\",\n                         (tenant, op)).fetchone()\n        return {\"status\": \"found\", \"version\": row[1], \"amount\": row[2]} if row else {\"status\": \"absent_now\"}\n\n\ndef main():\n    with tempfile.TemporaryDirectory() as directory:\n        path = str(Path(directory) / \"tool.sqlite\")\n        initialize(path)\n        altered = {**INTENT, \"amount\": 99}\n        wrong = apply(path, \"user-A\", \"K1\", altered, \"R18\", now=10)\n        assert wrong == \"approval_mismatch\"\n        claim, signature = signed_statement()\n        assert check_statement(claim, signature)\n        assert not check_statement({**claim, \"status\": \"failed\"}, signature)\n        unknown = lookup(path, \"user-A\", \"A\", \"K1\", injected_timeout=True)\n        assert unknown == {\"status\": \"unknown\"}\n        with connect(path) as db:\n            assert db.execute(\"SELECT count(*) FROM receipt\").fetchone()[0] == 0\n        # Commit in a real subprocess, then exit before returning a receipt to its caller.\n        child = subprocess.run([sys.executable, str(Path(__file__).resolve()), \"--crash\", path],\n                               capture_output=True, text=True, timeout=10)\n        assert child.returncode == 23, child.stderr\n        found = lookup(path, \"user-A\", \"A\", \"K1\")\n        assert found == {\"status\": \"found\", \"version\": 8, \"amount\": 37}\n        duplicate = apply(path, \"user-A\", \"K1\", INTENT, \"R18\", now=110)\n        assert duplicate == \"duplicate\"  # Current write permission + existing identical receipt.\n        conflict = apply(path, \"user-A\", \"K1\", altered, \"R18\", now=110)\n        assert conflict == \"conflict\"\n        cross_tenant = lookup(path, \"user-B\", \"A\", \"K1\")\n        assert cross_tenant == {\"status\": \"denied\"}\n        with connect(path) as db:\n            db.execute(\"UPDATE grants SET can_read=0,can_write=0 WHERE actor='user-A'\")\n        revoked = lookup(path, \"user-A\", \"A\", \"K1\")\n        assert revoked == {\"status\": \"denied\"}\n        assert apply(path, \"user-A\", \"K1\", INTENT, \"R18\", now=110) == \"denied\"\n        with connect(path) as db:\n            effects = db.execute(\"SELECT count(*) FROM receipt\").fetchone()[0]\n            final = db.execute(\"SELECT version,amount FROM draft\").fetchone()\n        assert effects == 1 and final == (8, 37)\n    print(json.dumps({\"changed_parameter\": wrong,\n                      \"signed_claim_valid_before_effect\": True,\n                      \"tampered_claim_rejected\": True,\n                      \"unavailable_receipt\": unknown[\"status\"],\n                      \"commit_then_exit_code\": child.returncode,\n                      \"authorized_receipt\": found, \"same_intent_retry\": duplicate,\n                      \"same_key_changed_intent\": conflict,\n                      \"cross_tenant_receipt\": cross_tenant[\"status\"],\n                      \"revoked_receipt\": revoked[\"status\"],\n                      \"effects\": effects, \"final_version\": final[0], \"final_amount\": final[1],\n                      \"scope\": \"trusted fixture, local HMAC, SQLite and process exit; no remote OAuth/MCP/Kairo\"}))\n\n\nif __name__ == \"__main__\":\n    if len(sys.argv) == 3 and sys.argv[1] == \"--crash\":\n        import os\n        if apply(sys.argv[2], \"user-A\", \"K1\", INTENT, \"R18\", now=10) != \"committed\":\n            raise RuntimeError(\"child did not commit\")\n        os._exit(23)\n    main()\n"};
