// serving-consistency-files.js
const servingConsistencyFiles={"cache_outbox.py": "\"\"\"Two local SQLite stores: source/outbox and a version-fenced cache receiver.\n\nThe source writer really exits after commit. Event delivery order is controlled.\nThis is not a Redis or MySQL implementation, nor a distributed atomic commit.\n\"\"\"\nfrom contextlib import closing\nimport json\nfrom pathlib import Path\nimport sqlite3\nimport subprocess\nimport sys\nimport tempfile\n\n\ndef connect(path):\n    return closing(sqlite3.connect(path, isolation_level=None))\n\n\ndef initialize_source(path):\n    with connect(path) as db:\n        db.executescript(\"\"\"\n        CREATE TABLE orders(tenant TEXT, id TEXT, version INT, state TEXT,\n                            PRIMARY KEY(tenant,id));\n        CREATE TABLE outbox(event TEXT PRIMARY KEY, tenant TEXT, id TEXT,\n                            version INT, delivered INT DEFAULT 0);\n        INSERT INTO orders VALUES('A','O-104',7,'pending');\n        \"\"\")\n\n\ndef initialize_cache(path):\n    with connect(path) as db:\n        db.executescript(\"\"\"\n        CREATE TABLE floor(tenant TEXT,id TEXT,version INT,PRIMARY KEY(tenant,id));\n        CREATE TABLE entry(tenant TEXT,id TEXT,version INT,state TEXT,PRIMARY KEY(tenant,id));\n        CREATE TABLE receipt(event TEXT PRIMARY KEY,tenant TEXT,id TEXT,version INT);\n        \"\"\")\n\n\ndef source_read(path):\n    with connect(path) as db:\n        return db.execute(\"SELECT version,state FROM orders WHERE tenant='A' AND id='O-104'\").fetchone()\n\n\ndef source_update(path, state, rollback=False):\n    with connect(path) as db:\n        db.execute(\"BEGIN IMMEDIATE\")\n        version = db.execute(\"SELECT version FROM orders WHERE tenant='A' AND id='O-104'\").fetchone()[0] + 1\n        db.execute(\"UPDATE orders SET version=?,state=? WHERE tenant='A' AND id='O-104'\", (version,state))\n        db.execute(\"INSERT INTO outbox(event,tenant,id,version) VALUES(?, 'A','O-104',?)\",\n                   (\"A:O-104:v\" + str(version), version))\n        if rollback:\n            db.rollback()\n            return \"rolled_back\"\n        db.commit()\n        return version\n\n\ndef cache_fill(path, snapshot):\n    version, state = snapshot\n    with connect(path) as db:\n        db.execute(\"BEGIN IMMEDIATE\")\n        floor = db.execute(\"SELECT version FROM floor WHERE tenant='A' AND id='O-104'\").fetchone()\n        current = db.execute(\"SELECT version FROM entry WHERE tenant='A' AND id='O-104'\").fetchone()\n        minimum = max(floor[0] if floor else 0, current[0] if current else 0)\n        if version < minimum:\n            db.rollback()\n            return \"stale_fill_rejected\"\n        db.execute(\"INSERT INTO entry VALUES('A','O-104',?,?) \"\n                   \"ON CONFLICT(tenant,id) DO UPDATE SET version=excluded.version,state=excluded.state\",\n                   (version,state))\n        db.commit()\n        return \"filled\"\n\n\ndef cache_read(path, minimum=0):\n    with connect(path) as db:\n        return db.execute(\"SELECT e.version,e.state FROM entry e LEFT JOIN floor f \"\n                          \"ON e.tenant=f.tenant AND e.id=f.id WHERE e.tenant='A' AND e.id='O-104' \"\n                          \"AND e.version>=MAX(COALESCE(f.version,0),?)\", (minimum,)).fetchone()\n\n\ndef deliver(cache, event):\n    event_id, tenant, key, version = event\n    with connect(cache) as db:\n        db.execute(\"BEGIN IMMEDIATE\")\n        previous = db.execute(\"SELECT tenant,id,version FROM receipt WHERE event=?\", (event_id,)).fetchone()\n        if previous:\n            db.rollback()\n            if previous != (tenant,key,version):\n                raise ValueError(\"event_identity_conflict\")\n            return \"duplicate\"\n        db.execute(\"INSERT INTO floor VALUES(?,?,?) ON CONFLICT(tenant,id) DO UPDATE \"\n                   \"SET version=MAX(floor.version,excluded.version)\", (tenant,key,version))\n        db.execute(\"DELETE FROM entry WHERE tenant=? AND id=? AND version < \"\n                   \"(SELECT version FROM floor WHERE tenant=? AND id=?)\", (tenant,key,tenant,key))\n        db.execute(\"INSERT INTO receipt VALUES(?,?,?,?)\", event)\n        db.commit()\n        return \"applied\"\n\n\ndef main():\n    with tempfile.TemporaryDirectory() as folder:\n        source, cache = (str(Path(folder)/name) for name in (\"source.sqlite\",\"cache.sqlite\"))\n        initialize_source(source)\n        initialize_cache(cache)\n        slow_snapshot = source_read(source)\n        assert cache_fill(cache, slow_snapshot) == \"filled\"\n        child = subprocess.run([sys.executable,str(Path(__file__).resolve()),\"--crash-writer\",source],\n                               capture_output=True,text=True,timeout=10)\n        assert child.returncode == 23, child.stderr\n        gap_cache, gap_source = cache_read(cache), source_read(source)\n        assert gap_cache == (7,\"pending\") and gap_source == (8,\"shipped\")\n        assert cache_read(cache, minimum=8) is None\n        minimum_version_result = source_read(source)\n        assert minimum_version_result[0] >= 8\n        assert source_update(source,\"bad\",rollback=True) == \"rolled_back\"\n        with connect(source) as db:\n            assert db.execute(\"SELECT count(*) FROM outbox\").fetchone()[0] == 1\n        assert source_read(source) == (8,\"shipped\")\n        assert source_update(source,\"delivered\") == 9\n        with connect(source) as db:\n            events = {row[3]:row for row in db.execute(\"SELECT event,tenant,id,version FROM outbox\")}\n        assert deliver(cache,events[9]) == \"applied\"\n        late_fill = cache_fill(cache,slow_snapshot)\n        assert late_fill == \"stale_fill_rejected\" and cache_read(cache) is None\n        assert cache_fill(cache,source_read(source)) == \"filled\"\n        assert deliver(cache,events[8]) == \"applied\"  # Old event must not lower the floor.\n        duplicate = deliver(cache,events[9])  # Simulate lost source-side acknowledgement.\n        assert duplicate == \"duplicate\" and cache_read(cache) == (9,\"delivered\")\n        try:\n            deliver(cache,(events[9][0],\"A\",\"O-104\",8))\n        except ValueError as error:\n            identity_conflict=str(error)\n        else:\n            raise AssertionError(\"event identity was reused with another version\")\n        assert identity_conflict == \"event_identity_conflict\"\n        with connect(source) as db:\n            db.execute(\"UPDATE outbox SET delivered=1 WHERE version IN (8,9)\")\n        with connect(cache) as db:\n            db.execute(\"DELETE FROM entry\")  # Eviction does not delete the version floor.\n        assert cache_fill(cache,slow_snapshot) == \"stale_fill_rejected\"\n        assert cache_fill(cache,source_read(source)) == \"filled\"\n        with connect(cache) as db:\n            final_floor = db.execute(\"SELECT version FROM floor\").fetchone()[0]\n        assert final_floor == 9\n        # Independent negative fixture: a cold cache lost both entries and historical floors.\n        reset = str(Path(folder)/\"lost-floor.sqlite\")\n        initialize_cache(reset)\n        assert deliver(reset,events[9]) == \"applied\"\n        with connect(reset) as db:\n            db.execute(\"DELETE FROM floor\")\n            db.execute(\"DELETE FROM entry\")\n        replay_after_floor_loss = deliver(reset,events[9])\n        assert replay_after_floor_loss == \"duplicate\"\n        with connect(reset) as db:\n            assert db.execute(\"SELECT count(*) FROM floor\").fetchone()[0] == 0\n        assert cache_fill(reset,slow_snapshot) == \"filled\"\n        lost_floor = cache_read(reset)\n        assert lost_floor == (7,\"pending\")\n        with connect(source) as db:\n            pending = db.execute(\"SELECT count(*) FROM outbox WHERE delivered=0\").fetchone()[0]\n        assert pending == 0\n        print(json.dumps({\"writer_commit_then_exit\":child.returncode,\n                          \"event_gap\":{\"cache\":gap_cache,\"source\":gap_source},\n                          \"minimum_version_8_read\":minimum_version_result,\n                          \"rollback_created_event\":False,\"delivery_order\":[9,8,9],\n                          \"late_fill\":late_fill,\"duplicate_delivery\":duplicate,\n                          \"event_identity_conflict\":identity_conflict,\n                          \"eviction_kept_floor\":True,\"final_floor\":final_floor,\n                          \"final_cache\":cache_read(cache),\"pending_outbox\":pending,\n                          \"lost_floor_negative\":lost_floor,\n                          \"replay_after_floor_loss\":replay_after_floor_loss,\n                          \"scope\":\"two local SQLite stores, controlled delivery; not Redis/MySQL or linearizable cache\"}))\n\n\nif __name__ == \"__main__\":\n    if len(sys.argv)==3 and sys.argv[1]==\"--crash-writer\":\n        import os\n        assert source_update(sys.argv[2],\"shipped\") == 8\n        os._exit(23)\n    main()\n", "serving_scheduler.py": "\"\"\"A deterministic iteration scheduler with separate work and reserved KV budgets.\n\nInteger microseconds; invented additive costs, no model, GPU or vLLM execution.\n\"\"\"\nfrom dataclasses import dataclass,field\nimport json\n\n\n@dataclass\nclass Request:\n    id: str\n    arrival: int\n    prompt: int\n    output_limit: int\n    prefilled: int = 0\n    admitted: int = -1\n    output_times: list = field(default_factory=list)\n\n    @property\n    def reservation(self):\n        # Prefill emits output #1. Only the next G-1 outputs need decode inputs.\n        positions = self.prompt + self.output_limit - 1\n        return ((positions+3)//4)*4\n\n\ndef simulate(spec,chunk,kv_capacity,work_budget=40):\n    if min(chunk,kv_capacity,work_budget)<=0:\n        raise ValueError(\"invalid_budget\")\n    requests = [Request(**row) for row in spec]\n    if len({r.id for r in requests}) != len(requests):\n        raise ValueError(\"duplicate_request_id\")\n    for r in requests:\n        if r.prompt<1 or r.output_limit<1 or r.arrival<0:\n            raise ValueError(\"invalid_request\")\n        if r.reservation>kv_capacity:\n            raise ValueError(\"request_exceeds_kv_budget\")\n    waiting = sorted(requests,key=lambda r:r.arrival)\n    active,trace,now,peak = [],[],0,0\n    while waiting or active:\n        if not active and waiting[0].arrival>now:\n            now=waiting[0].arrival\n        reserved=sum(r.reservation for r in active)\n        newcomers=[]\n        # FIFO admission; a non-fitting head remains queued, even if compute is free.\n        while waiting and waiting[0].arrival<=now:\n            r=waiting[0]\n            if reserved+r.reservation>kv_capacity:\n                break\n            waiting.pop(0);r.admitted=now;active.append(r);newcomers.append(r)\n            reserved+=r.reservation\n        peak=max(peak,reserved)\n        budget=work_budget\n        decoding=[r for r in active if r.prefilled==r.prompt][:budget]\n        budget-=len(decoding)\n        # New prompts first, then unfinished prompts in admission order; explicit toy policy.\n        prefilling=newcomers+[r for r in active if r not in newcomers and r.prefilled<r.prompt]\n        pieces=[]\n        for r in prefilling:\n            n=min(chunk,r.prompt-r.prefilled,budget)\n            if n:\n                r.prefilled+=n;budget-=n;pieces.append((r,n))\n        prompt_work=sum(n for _,n in pieces)\n        duration=100*prompt_work+1000*len(decoding)\n        assert duration>0 and prompt_work+len(decoding)<=work_budget\n        end=now+duration\n        emitted=[]\n        for r in decoding:\n            r.output_times.append(end);emitted.append(r.id)\n        for r,_ in pieces:\n            if r.prefilled==r.prompt:\n                r.output_times.append(end);emitted.append(r.id)\n        completed=[r for r in active if len(r.output_times)==r.output_limit]\n        trace.append({\"start_us\":now,\"end_us\":end,\"admitted\":[r.id for r in newcomers],\n                      \"decode\":[r.id for r in decoding],\"prefill\":{r.id:n for r,n in pieces},\n                      \"emitted\":emitted,\"reserved_before\":reserved,\n                      \"completed\":[r.id for r in completed]})\n        active=[r for r in active if r not in completed]\n        now=end\n    metrics={}\n    for r in requests:\n        assert len(r.output_times)==r.output_limit and r.prefilled==r.prompt\n        gaps=[b-a for a,b in zip(r.output_times,r.output_times[1:])]\n        metrics[r.id]={\"admitted_us\":r.admitted,\"waiting_us\":r.admitted-r.arrival,\n                       \"ttft_us\":r.output_times[0]-r.arrival,\"max_gap_us\":max(gaps) if gaps else None,\n                       \"last_us\":r.output_times[-1],\"output_times_us\":r.output_times,\n                       \"reserved_slots\":r.reservation}\n    assert peak<=kv_capacity\n    return {\"chunk\":chunk,\"kv_capacity\":kv_capacity,\"work_budget\":work_budget,\n            \"peak_reserved\":peak,\"finish_us\":now,\"requests\":metrics,\"trace\":trace}\n\n\ndef main():\n    arrival_case=[{\"id\":\"A\",\"arrival\":0,\"prompt\":32,\"output_limit\":4},\n                  {\"id\":\"B\",\"arrival\":2000,\"prompt\":4,\"output_limit\":2},\n                  {\"id\":\"C\",\"arrival\":2000,\"prompt\":8,\"output_limit\":2}]\n    streaming_case=[{\"id\":\"A\",\"arrival\":0,\"prompt\":4,\"output_limit\":6},\n                    {\"id\":\"B\",\"arrival\":500,\"prompt\":32,\"output_limit\":2}]\n    cases={}\n    for label,spec,capacity in [(\"new_short_prompt\",arrival_case,44),\n                               (\"long_prompt_while_streaming\",streaming_case,48)]:\n        cases[label]={\"whole\":simulate(spec,32,capacity),\"chunked\":simulate(spec,8,capacity)}\n    a=cases[\"new_short_prompt\"]\n    assert a[\"whole\"][\"requests\"][\"B\"][\"ttft_us\"]==2600\n    assert a[\"chunked\"][\"requests\"][\"B\"][\"ttft_us\"]==1600\n    assert a[\"whole\"][\"requests\"][\"A\"][\"ttft_us\"]==3200\n    assert a[\"chunked\"][\"requests\"][\"A\"][\"ttft_us\"]==3600\n    assert all(a[p][\"requests\"][\"C\"][\"admitted_us\"]==7600 for p in (\"whole\",\"chunked\"))\n    b=cases[\"long_prompt_while_streaming\"]\n    assert b[\"whole\"][\"requests\"][\"A\"][\"max_gap_us\"]==4200\n    assert b[\"chunked\"][\"requests\"][\"A\"][\"max_gap_us\"]==1800\n    assert b[\"whole\"][\"requests\"][\"B\"][\"ttft_us\"]==5100\n    assert b[\"chunked\"][\"requests\"][\"B\"][\"ttft_us\"]==8100\n    assert b[\"whole\"][\"finish_us\"]==b[\"chunked\"][\"finish_us\"]==9600\n    one=simulate([{\"id\":\"one\",\"arrival\":0,\"prompt\":4,\"output_limit\":1}],8,8)\n    assert one[\"requests\"][\"one\"][\"max_gap_us\"] is None\n    assert not any(step[\"decode\"] for step in one[\"trace\"])\n    try:\n        simulate([{\"id\":\"too-large\",\"arrival\":0,\"prompt\":64,\"output_limit\":2}],8,44)\n    except ValueError as error:\n        oversized=str(error)\n    else:\n        raise AssertionError(\"permanently non-fitting request was admitted\")\n    print(json.dumps({\"cases\":cases,\"one_output\":{\"ttft_us\":400,\"decode_steps\":0,\"max_gap_us\":None},\n                      \"oversized_request\":oversized,\n                      \"scope\":\"invented additive costs and full-length reservations; no actual model, GPU or vLLM\"}))\n\n\nif __name__ == \"__main__\":\n    main()\n", "retrieval_pipeline.py": "\"\"\"Controlled retrieval stages, task-visible body delivery, and independent grading.\n\nScores, rule reranking and costs are fixtures. No embedding, LLM or remote ACL.\n\"\"\"\nfrom fractions import Fraction\nimport json\nimport sqlite3\n\nGOLD={(\"a-1\",1),(\"a-2\",2)}  # Used only by the independent metric/answer grader.\nREQUIRED=(\"base\",\"adjustment\")\n\n\ndef database():\n    db=sqlite3.connect(\":memory:\",isolation_level=None)\n    db.row_factory=sqlite3.Row\n    db.executescript(\"\"\"\n    CREATE TABLE docs(tenant TEXT,id TEXT,version INT,kind TEXT,score REAL,\n                      units INT,body TEXT,PRIMARY KEY(tenant,id,version));\n    CREATE TABLE grants(actor TEXT,tenant TEXT,PRIMARY KEY(actor,tenant));\n    CREATE TABLE delivery(tenant TEXT,id TEXT,version INT);\n    INSERT INTO grants VALUES('user-A','A');\n    \"\"\")\n    docs=[(\"B\",\"b-secret\",1,\"base\",0.99,8,{\"amount\":999}),\n          (\"A\",\"a-2\",1,\"adjustment\",0.98,8,{\"amount\":99}),\n          (\"A\",\"a-note\",1,\"manual\",0.95,8,{\"text\":\"workflow notes\"}),\n          (\"A\",\"a-1\",1,\"base\",0.90,8,{\"amount\":10}),\n          (\"A\",\"a-2\",2,\"adjustment\",0.85,8,{\"amount\":27})]\n    db.executemany(\"INSERT INTO docs VALUES(?,?,?,?,?,?,?)\",\n                   [(*row[:6],json.dumps(row[6])) for row in docs])\n    return db\n\n\ndef permitted(db,meta,actor):\n    return db.execute(\"SELECT 1 FROM grants WHERE actor=? AND tenant=?\",(actor,meta[\"tenant\"])).fetchone() is not None\n\n\ndef current(db,meta):\n    latest=db.execute(\"SELECT MAX(version) FROM docs WHERE tenant=? AND id=?\",\n                      (meta[\"tenant\"],meta[\"id\"])).fetchone()[0]\n    return meta[\"version\"]==latest\n\n\ndef fetch_to_task(db,meta,actor,enforce=True):\n    # Recheck actual resource permissions and current version at body retrieval.\n    if enforce:\n        row=db.execute(\"SELECT d.body FROM docs d JOIN grants g ON g.tenant=d.tenant \"\n                       \"WHERE g.actor=? AND d.tenant=? AND d.id=? AND d.version=? \"\n                       \"AND d.version=(SELECT MAX(v.version) FROM docs v WHERE v.tenant=d.tenant AND v.id=d.id)\",\n                       (actor,meta[\"tenant\"],meta[\"id\"],meta[\"version\"])).fetchone()\n    else:\n        row=db.execute(\"SELECT body FROM docs WHERE tenant=? AND id=? AND version=?\",\n                       (meta[\"tenant\"],meta[\"id\"],meta[\"version\"])).fetchone()\n    if row is None:\n        raise PermissionError(\"resource_not_permitted_or_current\")\n    db.execute(\"INSERT INTO delivery VALUES(?,?,?)\",(meta[\"tenant\"],meta[\"id\"],meta[\"version\"]))\n    return {**meta,\"body\":json.loads(row[0])}\n\n\ndef metric(refs):\n    hits=set(refs[:2]) & GOLD\n    rank=next((i for i,ref in enumerate(refs[:2],1) if ref in GOLD),None)\n    return {\"precision_at_2\":str(Fraction(len(hits),2)),\n            \"recall_at_2\":str(Fraction(len(hits),len(GOLD))),\n            \"reciprocal_rank\":str(Fraction(1,rank)) if rank else \"0\"}\n\n\ndef execute(db,strategy,budget=16,revoke_before_fetch=False):\n    actor=\"user-A\"  # Trusted fixture session, not supplied by retrieved text.\n    metadata=[dict(row) for row in db.execute(\"SELECT tenant,id,version,kind,score,units FROM docs ORDER BY score DESC\")]\n    if strategy==\"unsafe_post_filter\":\n        # Intentional negative: these bodies have already entered the A task's buffer.\n        for meta in metadata[:2]:\n            fetch_to_task(db,meta,actor,enforce=False)\n        ranked=[m for m in metadata[:2] if permitted(db,m,actor) and current(db,m)]\n    elif strategy==\"post_filter\":\n        # Metadata-only filtering here does not itself disclose the rejected bodies.\n        ranked=[m for m in metadata[:2] if permitted(db,m,actor) and current(db,m)]\n    else:\n        eligible=[m for m in metadata if permitted(db,m,actor) and current(db,m)]\n        if strategy==\"pre_filter\":\n            ranked=eligible[:2]\n        elif strategy==\"rule_rerank\":\n            # A task-specific rule, not the GOLD set or a learned semantic reranker.\n            candidates=eligible[:3]\n            ranked=sorted(candidates,key=lambda m:(REQUIRED.index(m[\"kind\"]) if m[\"kind\"] in REQUIRED else 2,-m[\"score\"]))[:2]\n        else:\n            raise ValueError(\"unknown_strategy\")\n    selected=[]\n    remaining=budget\n    for meta in ranked:\n        if meta[\"units\"]<=remaining:\n            selected.append(meta);remaining-=meta[\"units\"]\n    if revoke_before_fetch:\n        db.execute(\"DELETE FROM grants WHERE actor=?\",(actor,))\n    context=[]\n    denied=False\n    for meta in selected:\n        try:\n            context.append(fetch_to_task(db,meta,actor))\n        except PermissionError:\n            denied=True\n            break\n    evidence={row[\"kind\"]:row for row in context if row[\"kind\"] in REQUIRED}\n    answer={\"status\":\"denied\" if denied else \"insufficient_evidence\"}\n    if not denied and set(evidence)==set(REQUIRED):\n        answer={\"status\":\"success\",\"total\":sum(evidence[k][\"body\"][\"amount\"] for k in REQUIRED),\n                \"citations\":[[evidence[k][\"id\"],evidence[k][\"version\"]] for k in REQUIRED]}\n    ranked_refs=[(m[\"id\"],m[\"version\"]) for m in ranked]\n    context_refs=[(m[\"id\"],m[\"version\"]) for m in context]\n    return {\"ranked\":ranked_refs,\"context\":context_refs,\"budget_units\":budget,\n            \"used_units\":sum(row[\"units\"] for row in context),\"answer\":answer}\n\n\ndef grade(db,result):\n    # Independent fixture oracle reads actual delivery rows; execution has no GOLD input.\n    deliveries=[dict(row) for row in db.execute(\"SELECT * FROM delivery\")]\n    forbidden=sum(row[\"tenant\"]!=\"A\" for row in deliveries)\n    obsolete=sum(not current(db,row) for row in deliveries)\n    answer=result[\"answer\"]\n    qualified=(answer.get(\"status\")==\"success\" and answer.get(\"total\")==37\n               and {tuple(x) for x in answer.get(\"citations\",[])}==GOLD and not forbidden and not obsolete)\n    return {\"rank_metrics\":metric(result[\"ranked\"]),\"context_metrics\":metric(result[\"context\"]),\n            \"forbidden_task_deliveries\":forbidden,\"obsolete_task_deliveries\":obsolete,\n            \"body_delivery_count\":len(deliveries),\"qualified_completion\":qualified}\n\n\ndef run(strategy,**kwargs):\n    db=database()\n    try:\n        result=execute(db,strategy,**kwargs)\n        return {**result,**grade(db,result)}\n    finally:\n        db.close()\n\n\ndef main():\n    cases={\"post_filter\":run(\"post_filter\"),\"pre_filter\":run(\"pre_filter\"),\n           \"rule_rerank_16\":run(\"rule_rerank\"),\"rule_rerank_12\":run(\"rule_rerank\",budget=12),\n           \"unsafe_post_filter\":run(\"unsafe_post_filter\"),\n           \"revoked_before_fetch\":run(\"rule_rerank\",revoke_before_fetch=True)}\n    assert cases[\"post_filter\"][\"ranked\"]==[] and cases[\"post_filter\"][\"body_delivery_count\"]==0\n    assert cases[\"pre_filter\"][\"rank_metrics\"]=={\"precision_at_2\":\"1/2\",\"recall_at_2\":\"1/2\",\"reciprocal_rank\":\"1/2\"}\n    assert cases[\"rule_rerank_16\"][\"qualified_completion\"]\n    low=cases[\"rule_rerank_12\"]\n    assert low[\"rank_metrics\"][\"recall_at_2\"]==\"1\" and low[\"context_metrics\"][\"recall_at_2\"]==\"1/2\"\n    assert low[\"context_metrics\"][\"reciprocal_rank\"]==\"1\" and not low[\"qualified_completion\"]\n    assert cases[\"unsafe_post_filter\"][\"forbidden_task_deliveries\"]==1\n    assert cases[\"unsafe_post_filter\"][\"obsolete_task_deliveries\"]==1\n    assert cases[\"revoked_before_fetch\"][\"answer\"]=={\"status\":\"denied\"}\n    assert cases[\"revoked_before_fetch\"][\"body_delivery_count\"]==0\n    assert all(not r[\"forbidden_task_deliveries\"] for k,r in cases.items() if k!=\"unsafe_post_filter\")\n    print(json.dumps({\"gold\":[[\"a-1\",1],[\"a-2\",2]],\"cases\":cases,\n                      \"scope\":\"fixed metadata scores, rule reranking, artificial units, SQLite bodies; no embedding/LLM/remote authorization\"}))\n\n\nif __name__ == \"__main__\":\n    main()\n"};
