// quantization-lessons.js
/* Derive the numbers before introducing engine-specific execution and evaluation. */
const quantMapping=infraReadableHTML(
 '<div class="mechanism-core" id="quantization-number-map">'+knowledgeSubhead('量化先做一件事：用有限整数表示一段数值')+
 para('设浮点权重w=1.2。若规定每个整数格代表0.02，且浮点0对应整数50，那么1.2就对应整数110。比例尺scale记为s，零点zero point记为z；反量化时，把整数减去零点，再乘回比例尺。整数本身不包含这些约定，读错s或z，恢复出的数就会不同。')+
 knowledgeFormula('一种仿射量化定义','q = clamp(round(w / s) + z, qmin, qmax)；ŵ = (q − z) × s',
 's必须为正，qmin/qmax规定整数范围；round的规则和饱和处理也属于格式契约。ŵ是近似恢复值，不保证等于原w。')+
 para('沿用s=0.02、z=50，若整数范围是[0,255]，1.2映射为110，恢复为1.2；4.6先映射为280，再被截到255，恢复只能得到4.1。这是范围外的裁剪误差。范围以内，无法恰好落在格点的数也要舍入。扩大范围可以减少裁剪，却会让格点更稀，细小差异更容易丢失。',
 '对称量化把零点固定为0，便于表达正负权重。本例INT4选择[-7,7]，用max(abs(w))/7确定比例尺；4bit编码本可表示[-8,7]，但本例不使用−8。不要把这份教学约定当作所有INT4格式。全零组另设s=1、q=0，避免除零。代码采用舍入到最近偶数，并先把s保存成float32，再用同一数值量化与回读。')+
 code('核心片段 · f32与输入定义见章末程序','PYTHON',
 'maximum = max(abs(w) for w in group)\nscale = f32(maximum / 7) if maximum else 1.0\nq = [max(-7, min(7, round(w / scale))) for w in group]\nrestored = [integer * scale for integer in q]')+
 para('量化不是把浮点数组直接astype成整数。直接转换既没有定义比例尺，也可能截掉小数或发生溢出；只改文件扩展名更不会让运行时理解低比特布局。先能从几个数手算q和恢复值，再看大模型方案，就容易分清它究竟改了哪一层。')+'</div>');

const quantGranularity=infraReadableHTML(
 knowledgeSubhead('整张量、每通道、分组：谁共享同一把比例尺')+
 para('线性层写作y=xWᵀ+b。本例W有4行、8列：8个输入特征产生4个输出，每一行是一组输出通道的权重。若32个权重共用一把比例尺，某个很大的值会把所有小值的格点一起拉开。按输出通道或更小的组分别选择比例尺，可以缩小这种影响范围，但要保存更多元数据。')+
 figure('v22-quant-groups','红色12是离群值。每4个权重一组时，只有它所在的组使用大间隔；其他组可以保留更细的数值。')+
 table(['粒度','本例组数','它控制的范围'],[
 ['per-tensor：整张量一组','1','32个权重共用s'],
 ['per-channel：每输出通道一组','4','每行8个权重共用s'],
 ['group size=4','8','沿每行输入维，每4个共用s'],
 ['group size=2','16','组更细，比例尺更多']])+
 para('“按通道”必须说清轴。把[输出,输入]布局的比例尺按另一条轴广播，数值会整体算错；矩阵转置、张量并行分片、重新打包后也要同步解释轴与组。真实引擎还可能要求固定分组大小、补齐和打包次序。格式名、权重尺寸、比例尺布局和对应算子要一起匹配。',
 '组更细不保证每个任务指标都单调变好。本例离群值分布使较小组的线性输出误差下降，但真实模型有多层传播、非线性和任务差异。对于有特别大激活或敏感通道的模型，可使用适合的校准、混合精度或保留少量高精度模块；应通过固定任务集判断收益，而不是只比较权重文件大小。'));

const quantStorage=infraReadableHTML(
 knowledgeSubhead('真把两个4bit值装进一个字节，再把元数据算进去')+
 para('Python列表里的整数不会因为数值小就只占4bit。要得到INT4载荷，需要实际打包。例：−7用4bit补码表示为1001，3表示为0011；若低4位保存前一项，两项合成00111001，即0x39。解包后，最高位为1的半字节要按有符号规则减16，不能把1001当成正9。奇数个权重的末半字节如何补齐，也要有固定约定。')+
 code('本例低位在前 · 两个有符号4bit值打包','PYTHON',
 'packed = (q0 & 0xF) | ((q1 & 0xF) << 4)\na = packed & 0xF\nb = (packed >> 4) & 0xF\nq0 = a - 16 if a >= 8 else a\nq1 = b - 16 if b >= 8 else b')+
 table(['32权重的存储方案','整数载荷','float32比例尺','张量载荷合计'],[
 ['FP16纯权重','64B','无该项','64B'],
 ['INT4整张量','16B','1×4B','20B'],
 ['INT4每通道','16B','4×4B','32B'],
 ['INT4每4个一组','16B','8×4B','48B'],
 ['INT4每2个一组','16B','16×4B','80B']])+
 para('下载程序还为形状和分组写入12B自定义文件头，因此group size=4的实际文件是60B。实际模型另有未量化模块、零点、索引、对齐与容器格式；不能拿“4bit是16bit的四分之一”预测整个模型文件。小张量或过细分组，元数据可以比整数载荷更大。',
 '再看一个量级题：假设70亿个权重全部从FP16改为INT4，每128个权重保存一个4B比例尺，不保存零点，且恰好整除。不含其他项时，FP16为14GB；INT4载荷3.5GB，比例尺0.21875GB，共3.71875GB。GB按10亿字节计。这只是这份格式的权重账，不包含KV缓存、激活、工作区或反量化临时对象，不能直接当作显存峰值。'));

const quantExecution=infraReadableHTML(
 knowledgeSubhead('W4A16与W8A8，描述的是不同对象的精度')+
 para('W指权重，A指参与相应算子的激活。W4A16通常表示4bit权重、16bit激活，但不单凭名称规定每个中间量、累加器或所有模块的类型。仅权重量化可以减少权重搬运；执行时可能先反量化到浮点，也可能在融合算子内边解包边参与计算。是否有匹配的高效算子，是独立于“文件已压缩”的问题。')+
 figure('v22-quant-execution','存储格式与算子路径一起决定成本。下面的CPU INT8程序实际替换了算子；INT4程序则专门核对字节与数学，不把两份结果混作一次验证。')+
 para('若权重和激活都对称量化，且单组比例尺分别为sw、sx，则点积近似为sx×sw×Σ(qx×qw)。整数乘加常用更宽类型累积，随后恢复比例并加偏置。范围和长度还要满足累加器的溢出约束；非零零点时，乘法里的零点修正项也不能漏。')+
 knowledgeFormula('权重沿输入维分为多组，且激活共用sx','y ≈ b + sx × Σg[ sw,g × Σi∈g(qx,i × qw,i) ]',
 '不同组的部分和先分别乘各自比例尺，再相加。把所有整数直接求和，最后统一乘第一组scale，会算成另一道题。')+
 para('显存也要看生命周期。如果先把整层INT4权重完整展开为FP16，而压缩权重还保留，两份可能同时驻留；再加工作区、激活和KV，峰值不一定等于压缩产物大小。融合反量化、分块加载、权重驻留和分片策略，会改变这些对象何时同时存在。报告时分别写清磁盘产物、常驻权重和运行峰值。',
 '性能比较保持相同模型目标、输入输出长度、并发与质量要求。权重带宽受限的场景可能获益；小矩阵、格式转换、算子回退或其他瓶颈也可能抵消收益。本地程序没有计时，不能从它的字节缩小比例推出真实服务加速比例。'));

const quantCalibration=infraReadableHTML(
 knowledgeSubhead('校准决定覆盖哪些数值，评估决定还能不能完成任务')+
 para('训练后量化（PTQ）在已有权重上选择量化参数与变换；量化感知训练（QAT）让训练过程感知相应量化误差。二者描述获得量化模型的路径，不直接规定服务端最终用哪个算子。校准样本用于观察分布或选择范围，与最后保留的任务评估集应分开；不能在评估集上反复调到满意，再把它当作独立检验。',
 '静态激活量化预先固定范围；动态方法在推理时按相应粒度观察输入，再计算比例尺。静态范围太窄会裁剪，太宽会降低分辨率；动态方案也有测量和缩放开销。下载实验把校准范围设为±0.5，保留输入却有一个3.0。静态方案裁剪1项，在同一已反量化权重上的最大输出误差约2.000225；覆盖当前范围的动态方案约0.06928。这是受控范围失配，不是“动态永远更好”的结论。')+
 table(['验收层','具体检查','不能替代什么'],[
 ['格式','维度、轴、组、比例尺、打包、加载后类型','不证明任务质量'],
 ['数值','层输出误差、异常值、有限性、关键边界','不证明答案和工具选择仍正确'],
 ['任务','中文、长文本、代码、数字、拒答与结构化输出的固定样本','不由少量线性输入直接外推'],
 ['服务','同口径延迟、吞吐、显存峰值、错误与回退比例','不只测最理想的短输入']])+
 para('小数值误差也可能改变选择。例如两个候选分数0.501和0.500，变成0.498和0.503后，绝对变化都很小，第一名却交换了。语言模型的一次选择还会影响后续生成。应单独统计格式错误、数字错误和任务通过率，并保留原高精度版本作为回退路径。固定版本的模型、分词器、量化配置、校准清单与评估清单，才能复查到底改变了什么。')+
 knowledgeCheck('量化后平均误差变小，就可以宣布服务更好吗？','还要检查误差落在哪些任务和边界，固定同一质量门槛再比较性能。输出尺寸正确、两组点积接近，只支持本例数值验证，不能替代真实中文任务评估。'));

const quantMethods=infraReadableHTML(
 knowledgeSubhead('行业常见方法，分别在解决哪一种误差')+
 para('了解表示、分组和校准后，再看GPTQ、AWQ、SmoothQuant，就能把名称放回具体步骤。它们不是一个通用文件后缀，也不自动带来相同精度和性能。选择方法后，还要确认导出布局与目标引擎真正兼容。')+
 table(['方法','主要改变什么','阅读时抓住的关键'],[
 ['GPTQ','利用近似二阶信息，处理训练后权重量化的重建误差','量化部分权重时怎样补偿误差；校准输入代表什么'],
 ['AWQ','根据激活分布识别敏感权重通道，以等价缩放降低低比特权重误差','不是只按权重最大值判断重要性；缩放后如何保持原浮点计算等价'],
 ['SmoothQuant','把部分激活离群值的量化困难转移给权重，服务于W8A8等路径','变换前后的浮点函数等价，量化后仍需重新评估'],
 ['QLoRA','冻结低比特基座，通过低秩适配器进行微调','训练的是适配参数；基座表示、激活与优化器状态分账']])+
 knowledgeFormula('用可逆对角矩阵D重分配数值范围','xWᵀ = (xD⁻¹)(WD)ᵀ',
 'D沿输入特征缩放。数学等价只说明变换前浮点函数不变；之后离散量化会再次引入误差。这里用于理解缩放思路，不是完整复现某篇算法。')+
 para('手算x=[2,4]、W=[3,−1]，输出2。取D=diag(2,0.5)，则xD⁻¹=[1,8]、WD=[6,−0.5]，新点积仍为6−4=2。一次变换让某些激活变小，却可能让另一侧权重变大；因此缩放系数要根据任务和量化范围选择，不能把所有通道无条件放大。',
 'GPTQ与AWQ都不能缩成“普通四舍五入的另一种名字”；SmoothQuant也不是只裁掉离群值。论文里的精度和速度来自其模型、数据、硬件与实现，迁移时要保留自己的校准与评估记录。本节程序只验证前面的INT4参考格式和CPU INT8路径，没有执行这四种完整方法。'));

const quantPractice=infraReadableHTML(
 knowledgeSubhead('先跑INT4格式参考，再跑真实CPU INT8算子')+
 sqcLab('int4_groups.py')+
 knowledgeSubhead('把“转换成功”验证到真正执行与产物回读')+
 para('第二份程序用PyTorch创建Linear(8,4)，实际替换为动态INT8模块，执行两组输入，再保存并加载自己生成的TorchScript。本次CPU后端为qnnpack，最大绝对误差约0.148362，低于本题预先设置的0.2；保存与加载后的量化输出差为0。0.2是这两组固定线性输入的教学阈值，不是语言模型质量标准。',
 '若遇到NoQEngine，先打印torch.backends.quantized.supported_engines与当前engine，确认安装包确实编译了可用CPU后端。本机初始engine为none，但支持qnnpack；程序在已有支持列表中选择后端后才转换。换成另一平台要使用其实际支持项；不要把这个错误解释成“没有GPU”，也不要假设把已量化CPU模块搬到CUDA就能使用同一种算子。')+
 sqcLab('int8_runtime.py')+
 para('练习：保持权重不变，把group size从4改为2，先计算比例尺数量与载荷，再预测误差变化，最后运行核对。再把激活的保留输入改成校准范围内和范围外各一组，解释哪一项是裁剪误差。最后写一份部署检查：目标设备、支持格式、量化对象、任务质量门槛、服务负载与回退条件；缺少哪项就保留哪项为待验证。'));

