const scalingCollectiveTraceFiles={"scaling_reference.py": "\"\"\"A bounded HPA resource-calculation reference and fluid queue; not a Kubernetes controller.\"\"\"\nfrom fractions import Fraction\nimport json\nimport math\n\n\ndef utilization(usage, requests):\n    # The examined Kubernetes v1.34.1 function uses the matching request sum,\n    # then integer percentage. Ready/missing classification happens elsewhere.\n    observed = [i for i, value in enumerate(usage) if value is not None]\n    if not observed or any(requests[i] <= 0 for i in observed):\n        raise ValueError(\"usage needs matching positive CPU requests\")\n    percent = sum(usage[i] for i in observed) * 100 // sum(requests[i] for i in observed)\n    return percent\n\n\ndef recommendation(usage, requests, target=60, current=None, tolerance=Fraction(1, 10)):\n    if current is None:\n        current = len(requests)\n    if len(usage) != len(requests) or not usage:\n        raise ValueError(\"matching nonempty Pod lists required\")\n    if target <= 0 or any(request <= 0 for request in requests):\n        raise ValueError(\"positive target and all Pod CPU requests required\")\n    known_percent = utilization(usage, requests)\n    before = Fraction(known_percent, target)\n    missing = [i for i, value in enumerate(usage) if value is None]\n    adjusted = list(usage)\n    if missing:\n        fill_percent = max(100, target) if before < 1 else 0\n        for i in missing:\n            adjusted[i] = requests[i] * fill_percent // 100\n        after_percent = utilization(adjusted, requests)\n    else:\n        after_percent = known_percent\n    after = Fraction(after_percent, target)\n    if abs(after - 1) <= tolerance:\n        proposed, reason = current, \"within_tolerance\"\n    elif (before < 1 < after) or (before > 1 > after):\n        proposed, reason = current, \"direction_reversed\"\n    else:\n        proposed = math.ceil(after * len(adjusted))\n        if (after < 1 and proposed > current) or (after > 1 and proposed < current):\n            proposed, reason = current, \"replica_direction_reversed\"\n        else:\n            reason = \"ratio_recommendation\"\n    return {\"observed_percent\": known_percent, \"adjusted_percent\": after_percent,\n            \"missing_pods\": len(missing), \"pre_policy_replicas\": proposed, \"reason\": reason}\n\n\ndef queue_model(new_capacity, limit=None, duration=150):\n    queue = dropped = completed = 0\n    rows = []\n    for second in range(duration):\n        capacity = 120 if second < 75 else new_capacity\n        available = queue + 180\n        done = min(available, capacity)\n        remaining = available - done\n        loss = max(0, remaining - limit) if limit is not None else 0\n        queue = remaining - loss\n        completed += done\n        dropped += loss\n        rows.append({\"end_second\": second + 1, \"capacity_per_second\": capacity,\n                     \"queue\": queue, \"completed_total\": completed, \"rejected_total\": dropped})\n    drained = next((row[\"end_second\"] for row in rows if row[\"end_second\"] > 75 and row[\"queue\"] == 0), None)\n    assert completed + dropped + queue == 180 * duration\n    return {\"peak_queue\": max(row[\"queue\"] for row in rows), \"final_queue\": queue,\n            \"completed\": completed, \"rejected\": dropped, \"drained_at_second\": drained,\n            \"samples\": [row for row in rows if row[\"end_second\"] in [1, 20, 35, 75, 76, 84, 100, 150]]}\n\n\ndef main():\n    cases = {\n        \"four_ready\": recommendation([180] * 4, [200] * 4),\n        \"requests_doubled\": recommendation([180] * 4, [400] * 4),\n        \"heterogeneous_requests\": recommendation([90, 90], [100, 900]),\n        \"missing_scale_up\": recommendation([180, 180, 180, None], [200] * 4),\n        \"missing_within_tolerance\": recommendation([170, 170, 170, None], [200] * 4),\n        \"missing_scale_down\": recommendation([60, 60, 60, None], [200] * 4),\n        \"missing_reverses_direction\": recommendation([20, None, None, None], [200] * 4),\n    }\n    assert [v[\"pre_policy_replicas\"] for v in cases.values()] == [6, 3, 1, 5, 4, 4, 4]\n    assert cases[\"missing_scale_down\"][\"adjusted_percent\"] == 47\n    # Wrong reference: arithmetic mean of each Pod's own percentage.\n    wrong = (Fraction(90, 100) + Fraction(90, 900)) / 2 * 100\n    assert wrong == 50 and cases[\"heterogeneous_requests\"][\"observed_percent\"] == 18\n    missing_request_rejected = False\n    try:\n        recommendation([180, None], [200, 0])\n    except ValueError:\n        missing_request_rejected = True\n    assert missing_request_rejected\n    history = [(0, 6), (60, 3), (180, 4), (301, 3), (481, 3)]\n    windows = [{\"now\": now, \"highest_in_last_300s\": max(value for time, value in history if now - 300 <= time <= now)}\n               for now in [60, 301, 481]]\n    assert [row[\"highest_in_last_300s\"] for row in windows] == [6, 4, 3]\n    queues = {\"only_match_arrival\": queue_model(180), \"extra_capacity\": queue_model(240),\n              \"bounded_queue\": queue_model(240, limit=500)}\n    assert queues[\"only_match_arrival\"][\"final_queue\"] == 4500\n    assert queues[\"extra_capacity\"][\"peak_queue\"] == 4500\n    assert queues[\"extra_capacity\"][\"drained_at_second\"] == 150\n    assert queues[\"bounded_queue\"][\"peak_queue\"] == 500\n    assert queues[\"bounded_queue\"][\"rejected\"] == 4000\n    assert queues[\"bounded_queue\"][\"drained_at_second\"] == 84\n    connection_budget = {\"database_limit\": 200, \"other_clients\": 80,\n                         \"connections_per_pod\": 40, \"max_pods\": (200 - 80) // 40,\n                         \"four_pods_max_each\": (200 - 80) // 4}\n    print(json.dumps({\"basis\": \"Kubernetes v1.34.1 resource-utilization calculation examined\",\n                      \"model_limits\": [\"all listed Pods treated as ready except missing metric\",\n                                       \"no real metrics API, controller loop, policy history or cluster\",\n                                       \"queue uses fixed fluid rates and one-second steps, not request latency\"],\n                      \"recommendations\": cases, \"wrong_mean_pod_percent\": float(wrong),\n                      \"missing_request_rejected\": missing_request_rejected,\n                      \"scale_down_window\": windows, \"queues\": queues,\n                      \"connection_budget\": connection_budget}, ensure_ascii=False, indent=2))\n\n\nif __name__ == \"__main__\":\n    main()\n\n", "prometheus_cpu.py": "\"\"\"Run the real promtool rule evaluator on four synthetic CPU fixtures.\"\"\"\nimport json\nfrom pathlib import Path\nimport subprocess\nimport sys\n\n\ndef main(binary):\n    executable = str(Path(binary).resolve()) if \"/\" in binary else binary\n    directory = Path(__file__).resolve().parent\n    commands = []\n    for arguments in [(\"check\", \"rules\", \"cpu.rules.yaml\"), (\"test\", \"rules\", \"cpu.test.yaml\")]:\n        result = subprocess.run([executable, *arguments], cwd=directory,\n                                capture_output=True, text=True, timeout=60)\n        if result.returncode:\n            raise RuntimeError(result.stdout + result.stderr)\n        commands.append({\"command\": \"promtool \" + \" \".join(arguments), \"exit_code\": 0})\n    version = subprocess.run([executable, \"--version\"], capture_output=True, text=True, check=True)\n    print(json.dumps({\"version\": (version.stdout + version.stderr).splitlines()[0],\n                      \"commands\": commands, \"fixture_groups\": 4,\n                      \"checks\": {\"different_requests\": {\"weighted_ratio\": 0.18, \"wrong_pod_mean\": 0.5},\n                                 \"missing_metric\": {\"naive_ratio\": 0.09, \"complete\": 0},\n                                 \"observed_zero\": {\"ratio\": 0, \"complete\": 1},\n                                 \"absent\": \"no_result_not_zero\"},\n                      \"scope\": \"actual_promtool_on_synthetic_gauges_not_metrics_server_or_hpa\"},\n                     ensure_ascii=False, indent=2))\n\n\nif __name__ == \"__main__\":\n    main(sys.argv[1] if len(sys.argv) > 1 else \"promtool\")\n\n", "collective_contracts.py": "\"\"\"Actual two-rank CPU/Gloo arithmetic, ragged gathering and collective-contract probes.\"\"\"\nfrom datetime import timedelta\nimport json\nimport re\nfrom pathlib import Path\nimport tempfile\nimport time\n\nimport torch\nimport torch.distributed as dist\nimport torch.multiprocessing as mp\n\n\ndef worker(rank, folder, mode):\n    torch.set_num_threads(1)\n    directory = Path(folder)\n    dist.set_debug_level(dist.DebugLevel.OFF if mode == \"correct\" else dist.DebugLevel.DETAIL)\n    dist.init_process_group(\"gloo\", init_method=(directory / \"rendezvous\").as_uri(),\n                            rank=rank, world_size=2, timeout=timedelta(seconds=12))\n    result = {\"rank\": rank, \"mode\": mode}\n    try:\n        if mode != \"correct\":\n            try:\n                tensor = torch.ones(2 if rank == 0 or mode == \"order_mismatch\" else 3)\n                if mode == \"order_mismatch\" and rank == 1:\n                    dist.broadcast(tensor, src=0)\n                else:\n                    dist.all_reduce(tensor)\n            except RuntimeError as error:\n                message = str(error)\n                operators = sorted(set(re.findall(r\"OpType=([A-Z_]+)\", message)))\n                shapes = sorted({part.split(\"]\", 1)[0] + \"]\" for part in message.split(\"TensorShape=\")[1:]})\n                result.update({\"rejected\": True,\n                               \"fingerprint_diagnostic\": \"CollectiveFingerPrint\" in message,\n                               \"category\": \"operation\" if len(operators) > 1 else \"shape\" if len(shapes) > 1 else \"other\",\n                               \"operators\": operators, \"shapes\": shapes,\n                               \"message_excerpt\": message[:1000]})\n            else:\n                raise AssertionError(\"mismatched collective unexpectedly succeeded\")\n        else:\n            original = torch.tensor([1, 2, 3, 4] if rank == 0 else [10, 20, 30, 40],\n                                    dtype=torch.float64)\n            summed = original.clone()\n            dist.all_reduce(summed, op=dist.ReduceOp.SUM)\n            assert summed.tolist() == [11, 22, 33, 44]\n            result[\"all_reduce_sum\"] = summed.tolist()\n            result[\"explicit_rank_mean\"] = (summed / 2).tolist()\n\n            shard = torch.zeros(2, dtype=original.dtype)\n            # Exercise this backend/version; do not infer every Gloo build supports every variant.\n            try:\n                dist.reduce_scatter_tensor(shard, original, op=dist.ReduceOp.SUM)\n                result[\"reduce_scatter_tensor\"] = {\"supported_here\": True, \"output\": shard.tolist()}\n                pieces = [torch.zeros_like(shard) for _ in range(2)]\n                dist.all_gather(pieces, shard)\n                reconstructed = torch.cat(pieces)\n                assert torch.equal(reconstructed, summed)\n                result[\"all_gather_shards\"] = reconstructed.tolist()\n            except RuntimeError as error:\n                if \"does not support\" not in str(error) and \"doesn't support\" not in str(error):\n                    raise\n                result[\"reduce_scatter_tensor\"] = {\"supported_here\": False, \"reason\": str(error)[:160]}\n\n            values = torch.tensor([2, 4, 6] if rank == 0 else [20], dtype=torch.float64)\n            length = torch.tensor([len(values)], dtype=torch.int64)\n            lengths = [torch.zeros_like(length) for _ in range(2)]\n            dist.all_gather(lengths, length)\n            lengths = [item.item() for item in lengths]\n            padded = torch.zeros(max(lengths), dtype=values.dtype)\n            padded[:len(values)] = values\n            gathered = [torch.zeros_like(padded) for _ in range(2)]\n            dist.all_gather(gathered, padded)\n            compact = [value for piece, size in zip(gathered, lengths) for value in piece[:size].tolist()]\n            totals = torch.tensor([values.sum().item(), len(values)], dtype=torch.float64)\n            dist.all_reduce(totals, op=dist.ReduceOp.SUM)\n            local_mean = values.mean().reshape(1)\n            dist.all_reduce(local_mean, op=dist.ReduceOp.SUM)\n            wrong_mean = local_mean.item() / 2\n            result[\"ragged\"] = {\"lengths\": lengths, \"gathered_padding\": [v.tolist() for v in gathered],\n                                \"real_values\": compact, \"sum\": totals[0].item(),\n                                \"count\": int(totals[1].item()), \"global_mean\": (totals[0]/totals[1]).item(),\n                                \"wrong_mean_of_means\": wrong_mean,\n                                \"wrong_include_padding_mean\": sum(compact)/(2*max(lengths))}\n            assert result[\"ragged\"][\"global_mean\"] == 8\n            assert wrong_mean == 12\n\n            dist.barrier()\n            if rank == 1:\n                time.sleep(0.08)  # Controlled pre-collective delay, not a network benchmark.\n            probe = torch.tensor([rank + 1], dtype=torch.int64)\n            started = time.perf_counter_ns()\n            work = dist.all_reduce(probe, op=dist.ReduceOp.SUM, async_op=True)\n            work.wait()\n            elapsed_ms = (time.perf_counter_ns() - started) / 1e6\n            assert probe.item() == 3\n            result[\"delayed_arrival\"] = {\"injected_pre_call_sleep_ms\": 80 if rank == 1 else 0,\n                                         \"local_call_and_wait_ms\": elapsed_ms,\n                                         \"result\": probe.item(), \"async_result_used_after_wait\": True}\n    finally:\n        dist.destroy_process_group()\n    (directory / (\"rank-\" + str(rank) + \".json\")).write_text(json.dumps(result))\n\n\ndef main():\n    modes = {}\n    with tempfile.TemporaryDirectory(prefix=\"infra-collective-\") as temporary:\n        for mode in [\"correct\", \"shape_mismatch\", \"order_mismatch\"]:\n            directory = Path(temporary) / mode\n            directory.mkdir()\n            mp.spawn(worker, args=(str(directory), mode), nprocs=2, join=True)\n            modes[mode] = [json.loads((directory / (\"rank-\" + str(rank) + \".json\")).read_text())\n                           for rank in range(2)]\n    for mode in [\"shape_mismatch\", \"order_mismatch\"]:\n        assert all(row[\"rejected\"] and row[\"fingerprint_diagnostic\"] for row in modes[mode])\n        expected_category = \"shape\" if mode == \"shape_mismatch\" else \"operation\"\n        assert all(row[\"category\"] == expected_category for row in modes[mode])\n    print(json.dumps({\"torch\": torch.__version__, \"backend\": \"gloo\", \"device\": \"cpu\", \"world_size\": 2,\n                      \"modes\": modes,\n                      \"scope\": \"actual_local_collectives_not_nccl_rdma_multihost_or_throughput\",\n                      \"timing_note\": \"Measured local call+wait durations vary; rank1 sleep is injected before its call.\"},\n                     ensure_ascii=False, indent=2))\n\n\nif __name__ == \"__main__\":\n    main()\n\n", "otel_attempts.py": "\"\"\"Actual OpenTelemetry SDK, W3C headers, two HTTP attempts and one SQLite effect.\"\"\"\nfrom http.server import BaseHTTPRequestHandler, HTTPServer\nfrom importlib.metadata import version\nimport json\nfrom pathlib import Path\nimport sqlite3\nimport tempfile\nimport threading\nimport time\nfrom urllib.error import HTTPError\nfrom urllib.request import Request, ProxyHandler, build_opener\n\nfrom opentelemetry.sdk.metrics import MeterProvider\nfrom opentelemetry.sdk.metrics.export import InMemoryMetricReader\nfrom opentelemetry.sdk.resources import Resource\nfrom opentelemetry.sdk.trace import TracerProvider\nfrom opentelemetry.sdk.trace.export import SimpleSpanProcessor\nfrom opentelemetry.sdk.trace.export.in_memory_span_exporter import InMemorySpanExporter\nfrom opentelemetry.sdk.trace.sampling import ALWAYS_ON\nfrom opentelemetry.trace import SpanKind, Status, StatusCode\nfrom opentelemetry.trace.propagation.tracecontext import TraceContextTextMapPropagator\n\n\ndef main():\n    exporter = InMemorySpanExporter()\n    traces = TracerProvider(sampler=ALWAYS_ON, resource=Resource.create({\"service.name\": \"infra-guide-runner\"}))\n    traces.add_span_processor(SimpleSpanProcessor(exporter))\n    tracer = traces.get_tracer(\"infra-guide.local-trace\", \"1\")\n    tool_traces = TracerProvider(sampler=ALWAYS_ON, resource=Resource.create({\"service.name\": \"infra-guide-tool\"}))\n    tool_traces.add_span_processor(SimpleSpanProcessor(exporter))\n    tool_tracer = tool_traces.get_tracer(\"infra-guide.local-trace\", \"1\")\n    reader = InMemoryMetricReader()\n    meters = MeterProvider(metric_readers=[reader], resource=Resource.create({\"service.name\": \"infra-guide-fixture\"}))\n    meter = meters.get_meter(\"infra-guide.local-trace\", \"1\")\n    attempts = meter.create_counter(\"lab.tool.attempts\", unit=\"{attempt}\")\n    effects = meter.create_counter(\"lab.tool.effects\", unit=\"{effect}\")\n    successes = meter.create_counter(\"lab.task.successes\", unit=\"{task}\")\n    cost = meter.create_counter(\"lab.teaching.cost\", unit=\"{unit}\")\n    duration = meter.create_histogram(\"lab.tool.duration\", unit=\"ms\")\n    propagator = TraceContextTextMapPropagator()\n    received_headers, ledger = [], []\n\n    with tempfile.TemporaryDirectory(prefix=\"infra-otel-\") as folder:\n        db = sqlite3.connect(str(Path(folder) / \"tool.sqlite\"), check_same_thread=False)\n        db.execute(\"CREATE TABLE effect(op TEXT PRIMARY KEY, total INTEGER)\")\n        server_calls = 0\n\n        class Handler(BaseHTTPRequestHandler):\n            def log_message(self, *args):\n                pass\n\n            def do_POST(self):\n                nonlocal server_calls\n                server_calls += 1\n                received_headers.append(self.headers[\"traceparent\"])\n                remote = propagator.extract(self.headers)\n                with tool_tracer.start_as_current_span(\"tool.execute\", context=remote,\n                                                   kind=SpanKind.SERVER) as span:\n                    data = json.loads(self.rfile.read(int(self.headers[\"Content-Length\"])))\n                    assert data == {\"op_id\": \"R27:publish\", \"total\": 37}\n                    span.set_attribute(\"app.op_id\", data[\"op_id\"])\n                    with db:\n                        old = db.execute(\"SELECT total FROM effect WHERE op=?\", (data[\"op_id\"],)).fetchone()\n                        if old:\n                            assert old[0] == data[\"total\"]\n                            duplicate = True\n                        else:\n                            db.execute(\"INSERT INTO effect VALUES(?,?)\", (data[\"op_id\"], data[\"total\"]))\n                            duplicate = False\n                    # Emit the committed event/counter only after the transaction context committed.\n                    span.add_event(\"receipt_reused\" if duplicate else \"effect_committed\")\n                    if not duplicate:\n                        effects.add(1, {\"tool\": \"report.write\"})\n                    span.set_attribute(\"app.duplicate\", duplicate)\n                    if server_calls == 1:\n                        # The effect has committed; now inject a failing HTTP response.\n                        span.set_attribute(\"http.response.status_code\", 503)\n                        span.set_status(Status(StatusCode.ERROR, \"injected_after_commit\"))\n                        self.send_response(503)\n                        self.send_header(\"Content-Length\", \"0\")\n                        self.end_headers()\n                        return\n                    body = json.dumps({\"op_id\": data[\"op_id\"], \"receipt\": \"receipt-1\",\n                                       \"total\": 37, \"duplicate\": duplicate}).encode()\n                    span.set_attribute(\"http.response.status_code\", 200)\n                    self.send_response(200)\n                    self.send_header(\"Content-Type\", \"application/json\")\n                    self.send_header(\"Content-Length\", str(len(body)))\n                    self.end_headers()\n                    self.wfile.write(body)\n\n        server = HTTPServer((\"127.0.0.1\", 0), Handler)\n        thread = threading.Thread(target=server.serve_forever, kwargs={\"poll_interval\": 0.01})\n        thread.start()\n        opener = build_opener(ProxyHandler({}))\n        endpoint = \"http://127.0.0.1:\" + str(server.server_port) + \"/reports\"\n        response_body = None\n        try:\n            with tracer.start_as_current_span(\"agent.task\") as task:\n                task.set_attribute(\"app.task_id\", \"R27\")\n                for number in [1, 2]:\n                    with tracer.start_as_current_span(\"tool.attempt\", kind=SpanKind.CLIENT) as span:\n                        span.set_attribute(\"app.task_id\", \"R27\")\n                        span.set_attribute(\"app.op_id\", \"R27:publish\")\n                        span.set_attribute(\"app.attempt\", number)\n                        headers = {\"Content-Type\": \"application/json\"}\n                        propagator.inject(headers)\n                        payload = json.dumps({\"op_id\": \"R27:publish\", \"total\": 37}).encode()\n                        started = time.perf_counter_ns()\n                        outcome = \"http_error\"\n                        try:\n                            request = Request(endpoint, payload, headers)\n                            with opener.open(request, timeout=3) as reply:\n                                response_body = json.load(reply)\n                            outcome = \"ok\"\n                            span.set_attribute(\"http.response.status_code\", 200)\n                        except HTTPError as error:\n                            assert error.code == 503 and number == 1\n                            span.set_attribute(\"http.response.status_code\", error.code)\n                            span.set_status(Status(StatusCode.ERROR, \"http_503_result_unknown\"))\n                            span.add_event(\"result_unknown\", {\"app.same_operation_retry\": True})\n                        finally:\n                            duration.record((time.perf_counter_ns() - started) / 1e6,\n                                            {\"tool\": \"report.write\"})\n                            attempts.add(1, {\"tool\": \"report.write\", \"outcome\": outcome})\n                            cost.add(2, {\"category\": \"tool_attempt\"})\n                            ledger.append({\"attempt\": number, \"teaching_cost_units\": 2, \"outcome\": outcome})\n                        if outcome == \"ok\":\n                            break\n                artifact = db.execute(\"SELECT op,total FROM effect\").fetchall()\n                assert artifact == [(\"R27:publish\", 37)]\n                assert response_body[\"duplicate\"] and response_body[\"receipt\"] == \"receipt-1\"\n                task.add_event(\"artifact_checked\", {\"app.accepted\": True})\n                task.set_attribute(\"app.outcome\", \"verified_success\")\n                task.set_status(Status(StatusCode.OK))\n                successes.add(1, {\"task_type\": \"report\"})\n                cost.add(1, {\"category\": \"verification\"})\n                ledger.append({\"stage\": \"verification\", \"teaching_cost_units\": 1})\n        finally:\n            server.shutdown()\n            server.server_close()\n            thread.join(timeout=5)\n            assert not thread.is_alive()\n            db.close()\n\n    spans = []\n    for span in sorted(exporter.get_finished_spans(), key=lambda s: s.start_time):\n        context = span.get_span_context()\n        spans.append({\"name\": span.name, \"kind\": span.kind.name,\n                      \"service\": span.resource.attributes[\"service.name\"],\n                      \"trace_id\": format(context.trace_id, \"032x\"), \"span_id\": format(context.span_id, \"016x\"),\n                      \"parent_id\": format(span.parent.span_id, \"016x\") if span.parent else None,\n                      \"parent_remote\": span.parent.is_remote if span.parent else False,\n                      \"status\": span.status.status_code.name,\n                      \"start_unix_ns\": str(span.start_time), \"end_unix_ns\": str(span.end_time),\n                      \"duration_ms\": (span.end_time - span.start_time) / 1e6,\n                      \"attributes\": dict(span.attributes),\n                      \"events\": [event.name for event in span.events]})\n    root = next(s for s in spans if s[\"name\"] == \"agent.task\")\n    clients = [s for s in spans if s[\"kind\"] == \"CLIENT\"]\n    servers = [s for s in spans if s[\"kind\"] == \"SERVER\"]\n    assert len(spans) == 5 and len(clients) == len(servers) == 2\n    assert len({s[\"trace_id\"] for s in spans}) == 1\n    assert all(s[\"parent_id\"] == root[\"span_id\"] for s in clients)\n    assert all(s[\"service\"] == \"infra-guide-runner\" for s in clients)\n    assert all(s[\"service\"] == \"infra-guide-tool\" for s in servers)\n    for client, remote, header in zip(clients, servers, received_headers):\n        assert remote[\"parent_id\"] == client[\"span_id\"] and remote[\"parent_remote\"]\n        assert header.split(\"-\")[1:3] == [client[\"trace_id\"], client[\"span_id\"]]\n    assert clients[0][\"status\"] == \"ERROR\" and root[\"status\"] == \"OK\"\n    metrics = []\n    data = reader.get_metrics_data()\n    for resource in data.resource_metrics:\n        for scope in resource.scope_metrics:\n            for metric in scope.metrics:\n                points = []\n                for point in metric.data.data_points:\n                    entry = {\"attributes\": dict(point.attributes)}\n                    if hasattr(point, \"value\"):\n                        entry[\"value\"] = point.value\n                    else:\n                        entry.update({\"count\": point.count, \"sum_ms\": point.sum})\n                    assert \"app.task_id\" not in entry[\"attributes\"] and \"app.op_id\" not in entry[\"attributes\"]\n                    points.append(entry)\n                metrics.append({\"name\": metric.name, \"unit\": metric.unit, \"points\": points})\n    sums = {m[\"name\"]: sum(p.get(\"value\", 0) for p in m[\"points\"]) for m in metrics}\n    assert sums[\"lab.tool.attempts\"] == 2\n    assert sums[\"lab.tool.effects\"] == sums[\"lab.task.successes\"] == 1\n    assert sums[\"lab.teaching.cost\"] == 5\n    result = {\"sdk\": version(\"opentelemetry-sdk\"), \"api\": version(\"opentelemetry-api\"),\n              \"spans\": spans, \"received_traceparent\": received_headers, \"metrics\": metrics,\n              \"http_attempts\": server_calls, \"effects\": 1, \"unique_verified_tasks\": 1,\n              \"cost_ledger\": ledger, \"all_attempt_cost_per_success\": 5,\n              \"success_http_attempt_only_cost\": 2,\n              \"pricing\": \"fixed_teaching_units_not_real_model_or_cloud_billing\",\n              \"scope\": \"actual_sdk_and_http_no_collector_backend_llm_kairo_or_real_auth\"}\n    meters.shutdown()\n    traces.shutdown()\n    tool_traces.shutdown()\n    print(json.dumps(result, ensure_ascii=False, indent=2))\n\n\nif __name__ == \"__main__\":\n    main()\n\n", "cpu.rules.yaml": "groups:\n  - name: lab-cpu-arithmetic\n    interval: 1m\n    rules:\n      - record: lab:cpu_utilization:ratio\n        expr: sum by (namespace, deployment) (lab_cpu_usage_cores) / sum by (namespace, deployment) (lab_cpu_request_cores)\n      - record: lab:mean_pod_utilization:ratio\n        expr: avg by (namespace, deployment) (lab_cpu_usage_cores / on (namespace, deployment, pod) lab_cpu_request_cores)\n      - record: lab:cpu_metrics_complete\n        expr: count by (namespace, deployment) (lab_cpu_usage_cores) == bool count by (namespace, deployment) (lab_cpu_request_cores)\n\n", "cpu.test.yaml": "rule_files:\n  - cpu.rules.yaml\nevaluation_interval: 1m\n# Permit only last-bit floating-point differences, keeping values and labels checked.\nfuzzy_compare: true\ntests:\n  - name: different-requests\n    interval: 1m\n    input_series:\n      - series: 'lab_cpu_usage_cores{namespace=\"apps\",deployment=\"reports\",pod=\"a\"}'\n        values: '0.09 0.09'\n      - series: 'lab_cpu_usage_cores{namespace=\"apps\",deployment=\"reports\",pod=\"b\"}'\n        values: '0.09 0.09'\n      - series: 'lab_cpu_request_cores{namespace=\"apps\",deployment=\"reports\",pod=\"a\"}'\n        values: '0.1 0.1'\n      - series: 'lab_cpu_request_cores{namespace=\"apps\",deployment=\"reports\",pod=\"b\"}'\n        values: '0.9 0.9'\n    promql_expr_test:\n      - expr: lab:cpu_utilization:ratio\n        eval_time: 1m\n        exp_samples:\n          - labels: 'lab:cpu_utilization:ratio{namespace=\"apps\",deployment=\"reports\"}'\n            value: 0.18\n      - expr: lab:mean_pod_utilization:ratio\n        eval_time: 1m\n        exp_samples:\n          - labels: 'lab:mean_pod_utilization:ratio{namespace=\"apps\",deployment=\"reports\"}'\n            value: 0.5\n      - expr: lab:cpu_metrics_complete\n        eval_time: 1m\n        exp_samples:\n          - labels: 'lab:cpu_metrics_complete{namespace=\"apps\",deployment=\"reports\"}'\n            value: 1\n  - name: missing-is-not-zero\n    interval: 1m\n    input_series:\n      - series: 'lab_cpu_usage_cores{namespace=\"apps\",deployment=\"reports\",pod=\"a\"}'\n        values: '0.09 0.09'\n      - series: 'lab_cpu_request_cores{namespace=\"apps\",deployment=\"reports\",pod=\"a\"}'\n        values: '0.1 0.1'\n      - series: 'lab_cpu_request_cores{namespace=\"apps\",deployment=\"reports\",pod=\"b\"}'\n        values: '0.9 0.9'\n    promql_expr_test:\n      - expr: lab:cpu_utilization:ratio\n        eval_time: 1m\n        exp_samples:\n          - labels: 'lab:cpu_utilization:ratio{namespace=\"apps\",deployment=\"reports\"}'\n            value: 0.09\n      - expr: lab:cpu_metrics_complete\n        eval_time: 1m\n        exp_samples:\n          - labels: 'lab:cpu_metrics_complete{namespace=\"apps\",deployment=\"reports\"}'\n            value: 0\n  - name: measured-zero-is-complete\n    interval: 1m\n    input_series:\n      - series: 'lab_cpu_usage_cores{namespace=\"apps\",deployment=\"reports\",pod=\"a\"}'\n        values: '0 0'\n      - series: 'lab_cpu_request_cores{namespace=\"apps\",deployment=\"reports\",pod=\"a\"}'\n        values: '0.1 0.1'\n    promql_expr_test:\n      - expr: lab:cpu_utilization:ratio\n        eval_time: 1m\n        exp_samples:\n          - labels: 'lab:cpu_utilization:ratio{namespace=\"apps\",deployment=\"reports\"}'\n            value: 0\n      - expr: lab:cpu_metrics_complete\n        eval_time: 1m\n        exp_samples:\n          - labels: 'lab:cpu_metrics_complete{namespace=\"apps\",deployment=\"reports\"}'\n            value: 1\n  - name: absent-telemetry\n    interval: 1m\n    input_series: []\n    promql_expr_test:\n      - expr: lab:cpu_metrics_complete\n        eval_time: 1m\n        exp_samples: []\n\n", "requirements-otel.txt": "opentelemetry-api==1.44.0\nopentelemetry-sdk==1.44.0\nopentelemetry-semantic-conventions==0.65b0\ntyping_extensions==4.16.0\n"};
